using System.Net.Http.Json;
using System.Text.Json.Serialization;

public class WeatherApiClient(HttpClient httpClient)
{
    public async Task<WeatherResponse?> GetCurrentWeatherAsync(
        double latitude, double longitude, CancellationToken ct = default)
    {
        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        return await httpClient.GetFromJsonAsync<WeatherResponse>(url, ct);
    }
}

public record WeatherResponse(
    [property: JsonPropertyName("current")] CurrentWeather? Current);

public record CurrentWeather(
    [property: JsonPropertyName("temperature_2m")] double Temperature,
    [property: JsonPropertyName("wind_speed_10m")] double WindSpeed);

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Get current weather for a location.")]
    public static async Task<string> GetCurrentWeather(
        WeatherApiClient weatherApi,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken ct)
    {
        var result = await weatherApi.GetCurrentWeatherAsync(latitude, longitude, ct);

        return result?.Current is { } c
            ? $"Temperature: {c.Temperature}°C, Wind: {c.WindSpeed} km/h"
            : "Weather data unavailable.";
    }
}

